import { Video } from "../types/video.ts";

export const analyzeViralPotential = (video: Video): Video => {
  let score = 0;
  const reasons: string[] = [];

  if (video.views > 100000) {
    score += 40;
    reasons.push("Alto volume de visualizações (>100k)");
  } else if (video.views > 10000) {
    score += 20;
    reasons.push("Bom volume de visualizações (>10k)");
  }

  if (video.views > 0) {
    const engagement = (video.likes / video.views) * 100;
    if (engagement > 5) {
      score += 30;
      reasons.push("Taxa de curtidas excelente (>5%)");
    } else if (engagement > 2) {
      score += 15;
      reasons.push("Boa taxa de curtidas");
    }
  }

  const hoursSincePublished = (new Date().getTime() - new Date(video.publishedAt).getTime()) / (1000 * 60 * 60);
  if (hoursSincePublished < 48) {
    score += 30;
    reasons.push("Publicado muito recentemente (<48h)");
  } else if (hoursSincePublished < 24 * 7) {
    score += 10;
    reasons.push("Publicado na última semana");
  }

  score = Math.min(score, 99);

  return {
    ...video,
    viralMetrics: {
      score,
      reasons,
    }
  };
};

import { YOUTUBE_CONSTANTS } from "../constants/youtube.ts";
import { validateYoutubeResponse } from "../validators/requestValidator.ts";
import { getEnv } from "../config/env.ts";

export const youtubeClient = {
  searchVideos: async (query: string, publishedAfter: string, maxResults: number) => {
    const apiKey = getEnv("YOUTUBE_API_KEY");
    const url = new URL(`${YOUTUBE_CONSTANTS.API_URL}/search`);
    url.searchParams.set("part", "snippet");
    url.searchParams.set("q", query);
    url.searchParams.set("type", "video");
    url.searchParams.set("maxResults", maxResults.toString());
    url.searchParams.set("publishedAfter", publishedAfter);
    url.searchParams.set("order", "viewCount");
    url.searchParams.set("key", apiKey);

    const response = await fetch(url.toString());
    const data = await response.json();
    return validateYoutubeResponse(data, "search");
  },

  getVideosStats: async (videoIds: string[]) => {
    if (videoIds.length === 0) return { items: [] };

    const apiKey = getEnv("YOUTUBE_API_KEY");
    const url = new URL(`${YOUTUBE_CONSTANTS.API_URL}/videos`);
    url.searchParams.set("part", "snippet,statistics,contentDetails");
    url.searchParams.set("id", videoIds.join(","));
    url.searchParams.set("key", apiKey);

    const response = await fetch(url.toString());
    const data = await response.json();
    return validateYoutubeResponse(data, "videos");
  }
};

export const getEnv = (key: string): string => {
  const value = Deno.env.get(key);
  if (!value) {
    throw new Error(`Environment variable ${key} is not set.`);
  }
  return value;
};

export const YOUTUBE_CONSTANTS = {
  API_URL: "https://www.googleapis.com/youtube/v3",
  DEFAULT_MAX_RESULTS: 50,
  MAX_RESULTS_LIMIT: 50,
  QUOTA_SEARCH: 100,
  QUOTA_VIDEO: 1,
};

import { serve } from "https://deno.land/std@0.177.0/http/server.ts";
import { handleError } from "./utils/errorHandler.ts";
import { logger } from "./utils/logger.ts";
import { parsePeriodToISO } from "./utils/date.ts";
import { parseQuery } from "./parsers/queryParser.ts";
import { validateSearchRequest } from "./validators/requestValidator.ts";
import { youtubeService } from "./services/youtubeService.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const startTime = Date.now();

  try {
    const rawBody = await req.json().catch(() => ({}));

    // 1. Validator
    const validatedRequest = validateSearchRequest(rawBody);

    // 2. Parser
    const parsedQuery = parseQuery(validatedRequest.query);
    const publishedAfter = parsePeriodToISO(validatedRequest.period);

    logger.info("Starting viral mining", { query: parsedQuery, period: validatedRequest.period });

    // 3. Service Orchestration
    const { videos, quotaUsed } = await youtubeService.searchVideos(
      parsedQuery,
      publishedAfter,
      validatedRequest.maxResults,
      validatedRequest.minViews
    );

    const executionTime = Date.now() - startTime;

    // 4. Build Context-Rich Response
    const responseBody = {
      success: true,
      search: {
        type: "hashtag",
        query: validatedRequest.query,
        parsedQuery,
        period: validatedRequest.period,
        minViews: validatedRequest.minViews
      },
      meta: {
        source: "youtube",
        executionTime,
        quotaUsed,
        totalResults: videos.length
      },
      videos,
    };

    logger.info("Mining complete", { executionTime, quotaUsed, totalResults: videos.length });

    return new Response(
      JSON.stringify(responseBody),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    const errorResponse = handleError(error);
    for (const [key, value] of Object.entries(corsHeaders)) {
      errorResponse.headers.set(key, value);
    }
    return errorResponse;
  }
});

import { Video } from "../types/video.ts";

export const mapToVideo = (processedRawVideo: any): Video => {
  const snippet = processedRawVideo.snippet || {};
  const stats = processedRawVideo.statistics || {};
  const contentDetails = processedRawVideo.contentDetails || {};

  // Find best thumbnail
  const thumbnails = snippet.thumbnails || {};
  const bestThumbnail = thumbnails.maxres?.url || thumbnails.high?.url || thumbnails.medium?.url || thumbnails.default?.url || "";

  return {
    id: processedRawVideo.id,
    title: snippet.title || "",
    channel: snippet.channelTitle || "",
    thumbnail: bestThumbnail,
    url: `https://www.youtube.com/watch?v=${processedRawVideo.id}`,
    description: snippet.description || "",
    publishedAt: snippet.publishedAt || "",
    views: stats.viewCount ? parseInt(stats.viewCount) : 0,
    likes: stats.likeCount ? parseInt(stats.likeCount) : 0,
    comments: stats.commentCount ? parseInt(stats.commentCount) : 0,
    duration: contentDetails.duration || "",
    hashtags: processedRawVideo.extractedHashtags || [],
    platform: "youtube",
    viralMetrics: { score: 0, reasons: [] },
  };
};

export const parseQuery = (rawQuery: string): string => {
  if (!rawQuery) return "";
  const trimmed = rawQuery.trim();

  // If it's a single word without `#`, add it.
  if (!trimmed.includes(" ") && !trimmed.startsWith("#")) {
    return `#${trimmed}`;
  }

  // Otherwise, return exactly as typed
  return trimmed;
};

export const processRawVideos = (rawVideos: any[]) => {
  // Remove duplicates
  const uniqueVideos = [];
  const ids = new Set();

  for (const v of rawVideos) {
    if (!v.id) continue;
    if (!ids.has(v.id)) {
      ids.add(v.id);

      // Extract hashtags from description and title
      const textToSearch = `${v.snippet?.title || ""} ${v.snippet?.description || ""}`;
      const hashtags = extractHashtags(textToSearch);

      uniqueVideos.push({
        ...v,
        extractedHashtags: hashtags,
      });
    }
  }

  return uniqueVideos;
};

const extractHashtags = (text: string): string[] => {
  if (!text) return [];
  const regex = /#[\w\u0590-\u05ff]+/ig;
  const matches = text.match(regex) || [];
  const uniqueTags = [...new Set(matches.map(t => t.toLowerCase()))];
  return uniqueTags;
};

import { youtubeClient } from "../clients/youtubeClient.ts";
import { processRawVideos } from "../processors/dataProcessor.ts";
import { mapToVideo } from "../mappers/videoMapper.ts";
import { analyzeViralPotential } from "../analyzers/viralAnalyzer.ts";
import { YOUTUBE_CONSTANTS } from "../constants/youtube.ts";

export const youtubeService = {
  searchVideos: async (parsedQuery: string, publishedAfter: string, maxResults: number, minViews: number) => {
    // 1. Fetch Search Results
    const searchData = await youtubeClient.searchVideos(parsedQuery, publishedAfter, maxResults);

    const videoIds = (searchData.items || [])
      .map((item: any) => item.id?.videoId)
      .filter(Boolean);

    if (videoIds.length === 0) {
      return { videos: [], quotaUsed: YOUTUBE_CONSTANTS.QUOTA_SEARCH };
    }

    // 2. Fetch Detailed Stats
    const statsData = await youtubeClient.getVideosStats(videoIds);
    const rawVideos = statsData.items || [];
    const quotaUsed = YOUTUBE_CONSTANTS.QUOTA_SEARCH + YOUTUBE_CONSTANTS.QUOTA_VIDEO;

    // 3. Pipeline
    const processedRaw = processRawVideos(rawVideos);
    let mappedVideos = processedRaw.map(mapToVideo);

    if (minViews > 0) {
      mappedVideos = mappedVideos.filter(v => v.views >= minViews);
    }

    const analyzedVideos = mappedVideos.map(analyzeViralPotential);
    analyzedVideos.sort((a, b) => b.viralMetrics.score - a.viralMetrics.score);

    return {
      videos: analyzedVideos,
      quotaUsed,
    };
  }
};

export interface Video {
  id: string;
  title: string;
  channel: string;
  thumbnail: string;
  url: string;
  description: string;
  publishedAt: string;
  views: number;
  likes: number;
  comments: number;
  duration: string;
  hashtags: string[];
  platform: string;
  viralMetrics: {
    score: number;
    reasons: string[];
  };
}

export const parsePeriodToISO = (period: string): string => {
  const now = new Date();
  const match = period.match(/^(\d+)(h|d|m)$/);
  if (!match) return new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(); // Default 7d

  const value = parseInt(match[1]);
  const unit = match[2];

  if (unit === 'h') {
    now.setHours(now.getHours() - value);
  } else if (unit === 'd') {
    now.setDate(now.getDate() - value);
  } else if (unit === 'm') {
    now.setMonth(now.getMonth() - value);
  }
  return now.toISOString();
};

import { logger } from "./logger.ts";

export const handleError = (error: any) => {
  logger.error("Function execution failed", { error: error.message, stack: error.stack });

  const code = error.code || "INTERNAL_ERROR";
  const message = error.message || "An unexpected error occurred.";
  const status = error.status || 500;

  return new Response(
    JSON.stringify({ success: false, code, message }),
    { status, headers: { "Content-Type": "application/json" } }
  );
};

export class AppError extends Error {
  constructor(public message: string, public code: string, public status: number = 400) {
    super(message);
    this.name = "AppError";
  }
}

export const logger = {
  info: (message: string, context?: any) => {
    console.log(JSON.stringify({ level: 'INFO', message, timestamp: new Date().toISOString(), ...context }));
  },
  error: (message: string, context?: any) => {
    console.error(JSON.stringify({ level: 'ERROR', message, timestamp: new Date().toISOString(), ...context }));
  }
};

import { AppError } from "../utils/errorHandler.ts";
import { YOUTUBE_CONSTANTS } from "../constants/youtube.ts";

export const validateSearchRequest = (body: any) => {
  if (!body || typeof body !== 'object') {
    throw new AppError("Invalid request body.", "INVALID_BODY", 400);
  }
  if (!body.query || typeof body.query !== "string") {
    throw new AppError("A valid query is required.", "INVALID_QUERY", 400);
  }

  const maxResults = body.maxResults ? parseInt(body.maxResults) : YOUTUBE_CONSTANTS.DEFAULT_MAX_RESULTS;
  if (maxResults > YOUTUBE_CONSTANTS.MAX_RESULTS_LIMIT) {
    throw new AppError(`Max results cannot exceed ${YOUTUBE_CONSTANTS.MAX_RESULTS_LIMIT}.`, "INVALID_MAX_RESULTS", 400);
  }

  return {
    query: body.query,
    period: body.period || "7d",
    minViews: body.minViews ? parseInt(body.minViews) : 0,
    maxResults,
  };
};

export const validateYoutubeResponse = (data: any, endpoint: string) => {
  if (data.error) {
    if (data.error.errors && data.error.errors[0]?.reason === 'quotaExceeded') {
      throw new AppError("YouTube API quota exceeded.", "QUOTA_EXCEEDED", 429);
    }
    throw new AppError(data.error.message || `YouTube API error on ${endpoint}`, "YOUTUBE_API_ERROR", 502);
  }
  if (!data.items) {
    throw new AppError(`Invalid response format from YouTube on ${endpoint}.`, "INVALID_YOUTUBE_RESPONSE", 502);
  }
  return data;
};
